#pragma once

#include <span>
#include <string_view>

// Globals whose contents the decomp keeps in the module images (initialised
// data, read-only data, images), not in C. The table is generated by
// tools/port/copy_to_native.py (Native\Game\src\Boot\ModuleData.cpp) from the
// data ledger and the decomp's splat configs: positions only, the bytes come
// from the user's disc at start-up.

namespace VS::Content {
struct ModuleDataEntry {
  const char* module;  // disc path of the module file (e.g. "TITLE/TITLE.PRG")
  unsigned offset;     // byte offset in that file
  unsigned size;       // bytes to copy (sizeof the native global)
  void* target;
  unsigned capacity;
};

extern const ModuleDataEntry kModuleData[];
extern const unsigned kModuleDataCount;

// Arrays of pointers kept in the module images (generated:
// Native\Game\src\Boot\ModulePointers.cpp). Each element on the disc is a PS1
// address; the loader resolves it through the symbol map: exactly for a
// function, within the symbol's extent for data.
struct ModuleSymbol {
  const char* module;
  unsigned address;  // PS1 address
  unsigned size;     // bytes (data); 0 for a function
  void* target;      // the native function or global
  unsigned nativeSize;
  unsigned sourceElementSize;
  unsigned nativeElementSize;
};

struct ModulePointerTable {
  const char* module;
  unsigned offset;  // byte offset of the table in the module file
  unsigned count;   // pointers
  void** target;    // the native array
  unsigned capacity;
  // LFO references are original short sample/control data, even at code labels.
  const ModuleSymbol* sample_source;
};

extern const ModuleSymbol kModuleSymbols[];
extern const unsigned kModuleSymbolCount;
extern const ModulePointerTable kModulePointers[];
extern const unsigned kModulePointerCount;

[[nodiscard]] inline std::span<const ModuleDataEntry> ModuleDataEntries() {
  return {kModuleData, kModuleDataCount};
}
[[nodiscard]] inline std::span<const ModuleSymbol> ModuleSymbols() {
  return {kModuleSymbols, kModuleSymbolCount};
}
[[nodiscard]] inline std::span<const ModulePointerTable> ModulePointerTables() {
  return {kModulePointers, kModulePointerCount};
}

bool CopyModuleDataEntry(const ModuleDataEntry& entry,
                         std::span<const unsigned char> image);
void* ResolveModuleAddress(std::span<const ModuleSymbol> symbols,
                           std::string_view module, unsigned address);
bool RelocateModulePointerTable(const ModulePointerTable& table,
                                std::span<const unsigned char> image,
                                std::span<const ModuleSymbol> symbols);
}  // namespace VS::Content
